"use client";

import * as React from "react";
import { BellRing, ShoppingBag } from "lucide-react";
import { Faces } from "./faces";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { StepperInput } from "./stepper-input";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * BUY BOX: the swatch that repaints the product
 *
 *   stage     the product stands on a pedestal of engraved rings
 *             in a stage painted in the colour you picked; a new
 *             colour floods the stage and ripples the rings
 *   options   swatches and sizes from your variants; what isn't
 *             made or is sold out is struck through; the price
 *             rolls when the variant costs more or less
 *   add       Add to bag goes Adding → Added and the product is
 *             thrown into the bag in the corner, which bumps as
 *             its count rolls
 *   sold out  the button becomes Notify me, and an email field
 *             grows out of it
 *
 * The catalogue is yours: pass options and variants (price and
 * stock per variant), and do the work in onAddToCart and onNotify.
 * Throw an Error and its message shows under the button.
 * ───────────────────────────────────────────────────────── */

export interface BuyBoxValue {
  id: string;
  label: string;
  /** A CSS colour: makes this a swatch, and paints the stage when picked. */
  swatch?: string;
}

export interface BuyBoxOption {
  id: string;
  /** e.g. "Colour", "Size". */
  label: string;
  values: BuyBoxValue[];
}

export interface BuyBoxVariant {
  id: string;
  /** The value id picked for each option, e.g. { colour: "sand", size: "m" }. */
  options: Record<string, string>;
  price: number;
  /** The old price, shown struck through. */
  compareAt?: number;
  /** Left in stock; leave out for plenty, 0 is sold out. */
  stock?: number;
  /** A photo of this variant; the stage shows `icon` when missing. */
  image?: string;
}

export interface BuyBoxProps {
  name: string;
  brand?: string;
  options: BuyBoxOption[];
  variants: BuyBoxVariant[];
  /** Starting picks; defaults to the first variant in stock. */
  defaultSelection?: Record<string, string>;
  /** The product's glyph on the stage when there's no image. */
  icon?: React.ReactNode;
  /** Items already in the bag. */
  bagCount?: number;
  /** "Only 3 left" from this many down. */
  lowStockAt?: number;
  /** Add to the bag; throw an Error to say why not. */
  onAddToCart: (variant: BuyBoxVariant, quantity: number) => Promise<unknown>;
  /** Shows Notify me on sold-out variants. */
  onNotify?: (variant: BuyBoxVariant, email: string) => Promise<unknown>;
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const money = (currency: string, n: number): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: 2,
});

const matches = (
  v: BuyBoxVariant,
  pick: Record<string, string>,
  skip?: string,
) =>
  Object.entries(pick).every(([k, val]) => k === skip || v.options[k] === val);

/** The pedestal: fine engraved rings the product stands on. */
function Rings({
  ringsRef,
}: {
  ringsRef: React.RefObject<SVGSVGElement | null>;
}) {
  return (
    <svg
      ref={ringsRef}
      aria-hidden="true"
      viewBox="0 0 200 80"
      className="absolute bottom-[6%] left-1/2 w-[78%] -translate-x-1/2 overflow-visible"
      fill="none"
      stroke="currentColor"
    >
      {Array.from({ length: 7 }, (_, i) => (
        <ellipse
          key={i}
          cx="100"
          cy="40"
          rx={30 + i * 12}
          ry={8 + i * 3.6}
          strokeWidth="0.8"
          strokeOpacity={0.34 - i * 0.04}
        />
      ))}
    </svg>
  );
}

export function BuyBox({
  name,
  brand,
  options,
  variants,
  defaultSelection,
  icon,
  bagCount = 0,
  lowStockAt = 5,
  onAddToCart,
  onNotify,
  currency = "USD",
  locale,
  className = "",
}: BuyBoxProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const [pick, setPick] = React.useState<Record<string, string>>(
    () =>
      defaultSelection ??
      (variants.find((v) => v.stock !== 0) ?? variants[0])?.options ??
      {},
  );
  const [quantity, setQuantity] = React.useState(1);
  const [add, setAdd] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [notify, setNotify] = React.useState<{
    open: boolean;
    email: string;
    status: ActionStatus;
    error?: string;
  }>({ open: false, email: "", status: "idle" });
  const [added, setAdded] = React.useState(0);
  const [ready, setReady] = React.useState(false);
  const [said, setSaid] = React.useState("");

  const sectionRef = React.useRef<HTMLElement>(null);
  const productRef = React.useRef<HTMLDivElement>(null);
  const bagRef = React.useRef<HTMLSpanElement>(null);
  const ringsRef = React.useRef<SVGSVGElement>(null);
  const emailRef = React.useRef<HTMLInputElement>(null);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  const variant =
    variants.find(
      (v) =>
        matches(v, pick) && options.every((o) => v.options[o.id] !== undefined),
    ) ?? null;
  const swatchOption = options.find((o) => o.values.some((v) => v.swatch));
  const swatch =
    swatchOption?.values.find((v) => v.id === pick[swatchOption.id])?.swatch ??
    "var(--primary)";
  const price = variant?.price ?? Math.min(...variants.map((v) => v.price));
  const soldOut = variant?.stock === 0;
  const low =
    variant?.stock !== undefined &&
    variant.stock > 0 &&
    variant.stock <= lowStockAt;
  const saving =
    variant?.compareAt && variant.compareAt > variant.price
      ? Math.round((1 - variant.price / variant.compareAt) * 100)
      : 0;
  const busy = add.status === "pending";
  const bag = bagCount + added;

  /** Is this value made with the rest of what's picked, and in stock? */
  const state = (optionId: string, valueId: string): "ok" | "out" | "none" => {
    const made = variants.filter(
      (v) => v.options[optionId] === valueId && matches(v, pick, optionId),
    );
    if (!made.length) return "none";
    return made.some((v) => v.stock !== 0) ? "ok" : "out";
  };

  const choose = (optionId: string, valueId: string) => {
    if (busy) return;
    const next = { ...pick, [optionId]: valueId };
    // Not made with the rest of the picks: move the others to the closest variant that is.
    const exact = variants.some((v) => matches(v, next));
    const fallback = exact
      ? next
      : (
          variants.find(
            (v) => v.options[optionId] === valueId && v.stock !== 0,
          ) ?? variants.find((v) => v.options[optionId] === valueId)
        )?.options;
    setPick(fallback ?? next);
    setAdd({ status: "idle" });
    if (notify.open)
      setNotify((n) => ({
        ...n,
        open: false,
        status: "idle",
        error: undefined,
      }));
    if (
      optionId === swatchOption?.id &&
      !reduced &&
      valueId !== pick[optionId]
    ) {
      // The rings are centred with `translate`, so the ripple only scales.
      ringsRef.current?.animate(
        [
          { transform: "scale(0.9)", opacity: 0.35 },
          { transform: "scale(1)", opacity: 1 },
        ],
        { duration: 620, easing: EASE_THROW },
      );
    }
  };

  // The product is thrown into the bag: a copy arcs from the stage to the bag, which bumps as it lands.
  const fly = () => {
    const section = sectionRef.current;
    const from = productRef.current;
    const to = bagRef.current;
    if (!section || !from || !to || reduced) {
      setAdded((n) => n + quantity);
      return;
    }
    const box = section.getBoundingClientRect();
    // Screen px to the block's own px, so the throw lands true inside a scaled or zoomed container too.
    const k = box.width / (section.offsetWidth || box.width) || 1;
    const a = from.getBoundingClientRect();
    const b = to.getBoundingClientRect();
    const copy = from.cloneNode(true) as HTMLElement;
    copy.setAttribute("aria-hidden", "true");
    Object.assign(copy.style, {
      position: "absolute",
      left: `${(a.left - box.left) / k}px`,
      top: `${(a.top - box.top) / k}px`,
      width: `${a.width / k}px`,
      height: `${a.height / k}px`,
      margin: "0",
      zIndex: "20",
      pointerEvents: "none",
      willChange: "transform",
    });
    section.appendChild(copy);
    const dx = (b.left + b.width / 2 - (a.left + a.width / 2)) / k;
    const dy = (b.top + b.height / 2 - (a.top + a.height / 2)) / k;
    const s = Math.min(b.height / a.height, 0.3);
    const flight = copy.animate(
      [
        { transform: "translate(0,0) scale(1)", opacity: 1 },
        {
          transform: `translate(${dx * 0.55}px, ${dy * 0.35 - 40}px) scale(${(1 + s) / 2}) rotate(-8deg)`,
          opacity: 1,
          offset: 0.5,
        },
        {
          transform: `translate(${dx}px, ${dy}px) scale(${s}) rotate(-14deg)`,
          opacity: 0.2,
        },
      ],
      { duration: 680, easing: "cubic-bezier(0.5,0,0.25,1)", fill: "forwards" },
    );
    flight.onfinish = flight.oncancel = () => {
      copy.remove();
      setAdded((n) => n + quantity);
      bagRef.current?.animate(
        [
          { transform: "scale(1)" },
          { transform: "scale(1.16)" },
          { transform: "scale(1)" },
        ],
        { duration: 420, easing: EASE_THROW },
      );
    };
  };

  const addToBag = async () => {
    if (!variant || busy || soldOut) return;
    setAdd({ status: "pending" });
    try {
      await onAddToCart(variant, quantity);
      setAdd({ status: "success" });
      setSaid(`Added ${quantity} ${name} to your bag.`);
      fly();
    } catch (e) {
      setAdd({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t add that. Try again.",
      });
    }
  };

  const sendNotify = async () => {
    if (!variant || !onNotify) return;
    if (!notify.open) {
      setNotify((n) => ({ ...n, open: true }));
      window.setTimeout(
        () => emailRef.current?.focus({ preventScroll: true }),
        reduced ? 0 : 300,
      );
      return;
    }
    if (!EMAIL.test(notify.email.trim()))
      return setNotify((n) => ({
        ...n,
        status: "idle",
        error: "Add an email we can write to",
      }));
    setNotify((n) => ({ ...n, status: "pending", error: undefined }));
    try {
      await onNotify(variant, notify.email.trim());
      setNotify((n) => ({ ...n, status: "success" }));
      setSaid("We’ll email you when it’s back.");
    } catch (e) {
      setNotify((n) => ({
        ...n,
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t save that. Try again.",
      }));
    }
  };

  const stock = soldOut
    ? "Sold out"
    : low
      ? `Only ${variant?.stock} left`
      : variant
        ? "In stock, ships today"
        : "Pick an option";
  const fmt = (n: number) => money(currency, n);

  return (
    <section
      ref={sectionRef}
      aria-labelledby={`${baseId}-name`}
      className={`relative w-full max-w-[400px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 400px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the stage, painted in the colour you picked. */}
        <div
          className="relative h-[220px] overflow-clip rounded-[22px]"
          style={{
            backgroundColor: mix(swatch, 48, "var(--card)"),
            backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("white", 34)} 0%, transparent 55%), linear-gradient(175deg, transparent 45%, ${mix("black", 14)} 100%)`,
            boxShadow: `inset 0 1px 0 ${mix("white", 40)}, inset 0 0 0 1px ${mix(swatch, 30)}`,
            color: mix(swatch, 62, "black"),
            transition: reduced
              ? "none"
              : `background-color 520ms ${EASE}, color 520ms ${EASE}, box-shadow 520ms ${EASE}`,
          }}
        >
          <Rings ringsRef={ringsRef} />
          <div
            ref={productRef}
            className="absolute inset-x-0 top-[14%] mx-auto flex size-[128px] items-center justify-center [&_svg]:size-[92px]"
          >
            {variant?.image ? (
              <img
                key={variant.image}
                src={variant.image}
                alt=""
                decoding="async"
                className="size-full object-contain motion-safe:animate-[ui-fade-in_420ms_ease-out_both]"
              />
            ) : (
              <span aria-hidden="true" className="flex [&_svg]:stroke-[1.2]">
                {icon ?? <ShoppingBag />}
              </span>
            )}
          </div>
          {saving > 0 && (
            <span className="absolute left-3 top-3 rounded-full bg-foreground px-2 py-1 text-[11.5px] font-medium tabular-nums text-background">
              −<NumberRoll value={saving} duration={600} />%
            </span>
          )}
          <span
            ref={bagRef}
            className="absolute right-3 top-3 inline-flex h-8 items-center gap-1.5 rounded-full bg-card px-3 text-[12.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
            aria-label={`${bag} in your bag`}
          >
            <ShoppingBag aria-hidden="true" className="size-3.5" />
            <NumberRoll value={bag} duration={600} aria-hidden="true" />
          </span>
        </div>

        <div className="px-2 pb-1 pt-3">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              {brand && (
                <p className="text-[12px] text-muted-foreground">{brand}</p>
              )}
              <h2
                id={`${baseId}-name`}
                className="text-[18px] font-medium leading-tight tracking-[-0.02em]"
              >
                {name}
              </h2>
            </div>
            <div className="shrink-0 text-right">
              <p className="text-[22px] font-medium leading-none tracking-[-0.03em] tabular-nums">
                <NumberRoll
                  value={price}
                  locales={locale}
                  format={fmt(price)}
                  duration={800}
                />
              </p>
              {saving > 0 && variant?.compareAt && (
                <p className="mt-1 text-[12px] text-muted-foreground tabular-nums line-through">
                  {new Intl.NumberFormat(
                    locale ?? (hydrated ? undefined : "en-US"),
                    fmt(variant.compareAt),
                  ).format(variant.compareAt)}
                </p>
              )}
            </div>
          </div>

          {options.map((o) => {
            const chosen = o.values.find((v) => v.id === pick[o.id]);
            return (
              <div key={o.id} className="mt-3.5">
                <p className="text-[12.5px] text-muted-foreground">
                  {o.label} ·{" "}
                  <TextMorph className="text-foreground">
                    {chosen?.label ?? "Choose"}
                  </TextMorph>
                </p>
                <div
                  role="radiogroup"
                  aria-label={o.label}
                  className="mt-2 flex flex-wrap gap-1.5"
                >
                  {o.values.map((v) => {
                    const on = v.id === pick[o.id];
                    const st = state(o.id, v.id);
                    const label = `${v.label}${st === "out" ? ", sold out" : st === "none" ? ", not made in this combination" : ""}`;
                    return v.swatch ? (
                      <button
                        key={v.id}
                        type="button"
                        role="radio"
                        aria-checked={on}
                        aria-label={label}
                        title={v.label}
                        onClick={() => choose(o.id, v.id)}
                        className={`relative size-8 cursor-pointer rounded-full ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                        style={{
                          background: v.swatch,
                          boxShadow: on
                            ? `inset 0 0 0 1px ${mix("black", 14)}, 0 0 0 2px var(--card), 0 0 0 3.5px var(--primary)`
                            : `inset 0 0 0 1px ${mix("black", 14)}, 0 0 0 2px var(--card), 0 0 0 2px transparent`,
                          opacity: st === "ok" ? 1 : 0.45,
                          transition: reduced
                            ? "none"
                            : `box-shadow 280ms ${EASE_THROW}, opacity 200ms`,
                        }}
                      >
                        {st !== "ok" && (
                          <span
                            aria-hidden="true"
                            className="absolute left-1/2 top-1/2 h-px w-[130%] -translate-x-1/2 -translate-y-1/2 -rotate-45 bg-foreground/60"
                          />
                        )}
                      </button>
                    ) : (
                      <button
                        key={v.id}
                        type="button"
                        role="radio"
                        aria-checked={on}
                        aria-label={label}
                        onClick={() => choose(o.id, v.id)}
                        className={`h-9 min-w-11 cursor-pointer rounded-full px-3 text-[13px] tabular-nums ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                          on
                            ? "bg-primary/[0.08] font-medium text-primary shadow-[inset_0_0_0_1.5px_var(--primary)]"
                            : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                        } ${st !== "ok" ? "text-muted-foreground line-through decoration-1" : ""}`}
                      >
                        {v.label}
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}

          <p
            className={`mt-3.5 flex items-center gap-1.5 text-[12.5px] ${soldOut ? "text-red-600 dark:text-red-400" : low ? "text-amber-600 dark:text-amber-400" : "text-muted-foreground"}`}
          >
            <span
              aria-hidden="true"
              className={`size-1.5 rounded-full ${soldOut ? "bg-red-500" : low ? "bg-amber-500" : "bg-emerald-500"}`}
            />
            <TextMorph>{stock}</TextMorph>
          </p>

          <div className="mt-2.5">
            <Faces active={notify.open ? 1 : 0} reduced={reduced} ready={ready}>
              <div className="flex items-center gap-2">
                <StepperInput
                  label="Quantity"
                  value={quantity}
                  min={1}
                  max={variant?.stock && variant.stock > 0 ? variant.stock : 10}
                  onValueChange={setQuantity}
                  disabled={soldOut || busy}
                />
                {soldOut && onNotify ? (
                  <button
                    type="button"
                    onClick={() => void sendNotify()}
                    className={`inline-flex h-11 flex-1 cursor-pointer items-center justify-center gap-2 rounded-full text-[14.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                  >
                    <BellRing aria-hidden="true" className="size-4" />
                    Notify me
                  </button>
                ) : (
                  <StatusButton
                    status={add.status}
                    labels={{
                      idle: soldOut ? "Sold out" : "Add to bag",
                      pending: "Adding",
                      success: "Added",
                      error: "Try again",
                    }}
                    icon={<ShoppingBag aria-hidden="true" />}
                    disabled={!variant || soldOut}
                    onReset={() => setAdd({ status: "idle" })}
                    resetAfter={1500}
                    onClick={() => void addToBag()}
                    className="h-11 flex-1 text-[14.5px] disabled:opacity-45"
                    style={add.status === "error" ? undefined : LIT}
                  />
                )}
              </div>
              <form
                className="flex items-start gap-2"
                onSubmit={(e) => {
                  e.preventDefault();
                  void sendNotify();
                }}
              >
                <Input
                  ref={emailRef}
                  aria-label="Email for a restock note"
                  type="email"
                  inputMode="email"
                  autoComplete="email"
                  placeholder="you@email.com"
                  value={notify.email}
                  error={notify.error}
                  disabled={
                    notify.status === "pending" || notify.status === "success"
                  }
                  onValueChange={(email) =>
                    setNotify((n) => ({
                      ...n,
                      email,
                      error: undefined,
                      status: n.status === "error" ? "idle" : n.status,
                    }))
                  }
                  className="flex-1"
                />
                <StatusButton
                  type="submit"
                  status={notify.status}
                  labels={{
                    idle: "Notify me",
                    pending: "Saving",
                    success: "You’re on the list",
                    error: "Try again",
                  }}
                  className="h-9 shrink-0 px-4 text-[13px]"
                  style={notify.status === "error" ? undefined : LIT}
                />
              </form>
            </Faces>
            {add.error && (
              <p
                role="alert"
                className="mt-1.5 text-[12px] text-red-600 dark:text-red-400"
              >
                {add.error}
              </p>
            )}
          </div>
        </div>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default BuyBox;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * FACES: the states of one surface, in the same place
 *
 * The active face is in flow; the others are laid over it, faded
 * and nudged aside (faces before it to the left, faces after it to
 * the right), so switching reads as the surface turning to its
 * next side. The height eases between the faces' measured heights,
 * so nothing around it jumps. Used by the blocks (the wallet's
 * activity and keypad, a pricing card and its checkout, a booking's
 * times, details and confirmation).
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16,1,0.3,1)";
export const FACES_MORPH = 460;

export function Faces({
  active,
  reduced,
  ready,
  className = "",
  children,
}: {
  active: number;
  reduced: boolean;
  /** False until the first paint, so the faces don't animate into place on mount. */
  ready: boolean;
  className?: string;
  children: React.ReactNode[];
}) {
  const refs = React.useRef<(HTMLDivElement | null)[]>([]);
  const [heights, setHeights] = React.useState<number[] | null>(null);
  const count = children.length;

  React.useLayoutEffect(() => {
    const els = refs.current.slice(0, count);
    const observer = new ResizeObserver(() => {
      const next = els.map((el) => el?.offsetHeight ?? 0);
      setHeights((p) =>
        p && p.length === next.length && p.every((h, i) => h === next[i])
          ? p
          : next,
      );
    });
    els.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [count]);

  const face = (i: number): React.CSSProperties => {
    const on = i === active;
    return {
      opacity: on ? 1 : 0,
      transform:
        on || reduced ? "none" : `translateX(${i < active ? -18 : 18}px)`,
      filter: on || reduced ? "none" : "blur(4px)",
      transition: !ready
        ? "none"
        : reduced
          ? "opacity 160ms ease-out"
          : on
            ? `opacity 320ms ${EASE} 90ms, transform ${FACES_MORPH}ms ${EASE}, filter 320ms ${EASE} 90ms`
            : `opacity 140ms ease-out, transform ${FACES_MORPH}ms ${EASE}, filter 200ms ease-out`,
    };
  };

  return (
    <div
      className={`relative overflow-clip ${className}`}
      style={{
        height: heights ? heights[active] : undefined,
        transition:
          ready && !reduced ? `height ${FACES_MORPH}ms ${EASE}` : "none",
      }}
    >
      {children.map((child, i) => (
        <div
          key={i}
          ref={(el) => {
            refs.current[i] = el;
          }}
          inert={active !== i || undefined}
          aria-hidden={active !== i || undefined}
          className={
            active === i
              ? "relative"
              : "pointer-events-none absolute inset-x-0 top-0"
          }
          style={face(i)}
        >
          {child}
        </div>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Field,
  fieldSurface,
  setNativeValue,
  useFieldIds,
  useShake,
  type FieldSize,
} from "./imported-field";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * INPUT: a one-line field
 *
 *   rest     a thin line pill; hover darkens the line
 *   focus    the line turns to the ring with a 3px halo
 *   typing   a clear button folds in once there is text and
 *            folds away when it's gone (it hands focus back)
 *   error    the line turns red, the hint gives way to the
 *            error and the field shakes once
 * ───────────────────────────────────────────────────────── */

export interface InputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "size"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  /** Shows red and replaces the hint. */
  error?: React.ReactNode;
  /** An icon or text before the value. */
  leading?: React.ReactNode;
  /** An icon, text or button after the value. */
  trailing?: React.ReactNode;
  /** A button that empties the field once it has text. */
  clearable?: boolean;
  /** 28px or 36px tall. */
  size?: FieldSize;
  /** Called with the new text on every change. */
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLInputElement>;
  /** Class for the outer column. */
  className?: string;
  /** Class for the input element itself. */
  inputClassName?: string;
}

function ClearIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Input({
  label,
  hint,
  error,
  leading,
  trailing,
  clearable,
  size = "md",
  onValueChange,
  ref,
  id,
  className = "",
  inputClassName = "",
  value,
  defaultValue,
  onChange,
  disabled,
  required,
  ...props
}: InputProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const inner = React.useRef<HTMLInputElement>(null);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const shakeRef = useShake<HTMLDivElement>(!!error);
  const sm = size === "sm";
  const showClear = !!clearable && current.length > 0 && !disabled;

  const setRefs = (el: HTMLInputElement | null) => {
    inner.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLInputElement | null>).current = el;
  };

  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled })} ${sm ? "h-7 text-[16px] sm:text-[12.5px]" : "h-9 text-[16px] sm:text-[13.5px]"}`}
      >
        {leading && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pl-2.5" : "pl-3.5"} [&_svg]:size-3.5`}
          >
            {leading}
          </span>
        )}
        <input
          ref={setRefs}
          id={ids.id}
          value={value}
          defaultValue={defaultValue}
          disabled={disabled}
          required={required}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          onChange={(e) => {
            if (value === undefined) setText(e.target.value);
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          className={`h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground/70 ${leading ? "pl-2" : sm ? "pl-3" : "pl-4"} ${trailing || clearable ? "pr-1" : sm ? "pr-3" : "pr-4"} ${inputClassName}`}
          {...props}
        />
        {clearable && (
          // The clear button folds its own width open, so the text never jumps.
          <span
            className="grid shrink-0"
            style={{
              gridTemplateColumns: showClear ? "1fr" : "0fr",
              transition: reduced
                ? "none"
                : `grid-template-columns 320ms ${EASE_OUT}`,
            }}
          >
            <span className="min-w-0 overflow-hidden">
              <button
                type="button"
                tabIndex={showClear ? 0 : -1}
                aria-hidden={!showClear}
                aria-label="Clear"
                onClick={() => {
                  if (!inner.current) return;
                  setNativeValue(inner.current, "");
                  inner.current.focus();
                }}
                className={`mr-1 flex items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${sm ? "size-5" : "size-7"} ${INTERACTION_FOCUS}`}
                style={interactionIcon(showClear, reduced)}
              >
                <ClearIcon />
              </button>
            </span>
          </span>
        )}
        {trailing && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pr-1" : "pr-1.5"} [&_svg]:size-3.5`}
          >
            {trailing}
          </span>
        )}
      </div>
    </Field>
  );
}

export default Input;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
              : show
                ? `opacity 280ms ${EASE_OUT} 60ms, filter 280ms ${EASE_OUT} 60ms, transform 380ms ${EASE_OUT}`
                : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 200ms ${EASE_OUT}`,
          }}
        >
          {show ? children : kept}
        </p>
      </div>
    </div>
  );
}

export function Field({
  id,
  label,
  aside,
  hint,
  error,
  required,
  className = "",
  children,
}: FieldProps) {
  const reduced = useInteractionReducedMotion();
  const ids = { hint: `${id}-hint`, error: `${id}-error` };
  return (
    <div className={`flex w-full flex-col ${className}`}>
      {(label || aside) && (
        <div className="flex items-baseline justify-between gap-3 px-3 pb-1.5">
          {label && (
            <label
              htmlFor={id}
              className="text-[13px] font-medium text-foreground"
            >
              {label}
              {required && (
                <span
                  aria-hidden="true"
                  className="ml-0.5 text-muted-foreground"
                >
                  *
                </span>
              )}
            </label>
          )}
          {aside && (
            <span className="text-[12px] tabular-nums text-muted-foreground">
              {aside}
            </span>
          )}
        </div>
      )}
      {children}
      <Line
        show={!error && !!hint}
        id={ids.hint}
        tone="text-muted-foreground"
        reduced={reduced}
      >
        {hint}
      </Line>
      <Line
        show={!!error}
        id={ids.error}
        tone="text-red-600 dark:text-red-400"
        reduced={reduced}
      >
        {error}
      </Line>
    </div>
  );
}

export default Field;

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STEPPER INPUT: a tactile number control with acceleration
 *
 *   single tap   increments or decrements by step, rolling
 *                the odometer in the direction of travel
 *   holding      waits 300ms, then accelerates smoothly from
 *                100ms down to 30ms intervals with scaled steps
 *   boundary     hitting min or max bounds disables the action
 *                and gives the container an elastic bumper shake
 *   direct edit  clicking the number reveals an exact input,
 *                committing on blur or Enter, cancelling on Escape
 * ───────────────────────────────────────────────────────── */

export interface StepperInputProps {
  /** Accessible label, e.g. "Team seats" or "Border radius". */
  label: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Large step for PageUp/PageDown and prolonged acceleration. Defaults to step * 10. */
  largeStep?: number;
  /** Optional unit appended to the number, e.g. "px", "%", "seats". */
  unit?: string;
  /** Format options passed to NumberRoll when not editing. */
  format?: Intl.NumberFormatOptions;
  /** Visual variant: "pill" for rounded-full, "field" for standard form input. */
  variant?: "pill" | "field";
  size?: "sm" | "default";
  disabled?: boolean;
  name?: string;
  className?: string;
}

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function MinusIcon({ className = "size-3.5" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M3.5 8h9"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

function PlusIcon({ className = "size-3.5" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M8 3.5v9M3.5 8h9"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

const shake = (el: HTMLElement | null, reduced: boolean) => {
  if (!el || reduced) return;
  el.animate(
    [
      { transform: "none" },
      { transform: "translateX(-3px)" },
      { transform: "translateX(3px)" },
      { transform: "translateX(-1.5px)" },
      { transform: "none" },
    ],
    { duration: 280, easing: "ease-out", composite: "add" },
  );
};

export function StepperInput({
  label,
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  min = -Infinity,
  max = Infinity,
  step = 1,
  largeStep,
  unit,
  format,
  variant = "pill",
  size = "default",
  disabled = false,
  name,
  className = "",
}: StepperInputProps) {
  const reduced = useReducedMotion();
  const [uncontrolledValue, setUncontrolledValue] =
    React.useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const currentVal = isControlled ? controlledValue : uncontrolledValue;

  const [editing, setEditing] = React.useState(false);
  const [editText, setEditText] = React.useState(String(currentVal));

  const rootRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const holdTimerRef = React.useRef<number | null>(null);
  const holdIntervalRef = React.useRef<number | null>(null);
  const holdStartRef = React.useRef<number>(0);

  const effectiveLargeStep = largeStep ?? step * 10;
  const atMin = currentVal <= min;
  const atMax = currentVal >= max;

  const clamp = React.useCallback(
    (n: number) => {
      let rounded = Math.round(n / step) * step;
      // Fix floating point precision, e.g. 0.1 + 0.2
      const stepDecimals = (step.toString().split(".")[1] || "").length;
      if (stepDecimals > 0) {
        rounded = Number(rounded.toFixed(stepDecimals));
      }
      return Math.min(max, Math.max(min, rounded));
    },
    [min, max, step],
  );

  const updateVal = React.useCallback(
    (nextRaw: number) => {
      const next = clamp(nextRaw);
      if (next === currentVal) {
        shake(rootRef.current, reduced);
        return false;
      }
      if (!isControlled) {
        setUncontrolledValue(next);
      }
      onValueChange?.(next);
      return true;
    },
    [clamp, currentVal, isControlled, onValueChange, reduced],
  );

  const stopHold = React.useCallback(() => {
    if (holdTimerRef.current !== null) {
      window.clearTimeout(holdTimerRef.current);
      holdTimerRef.current = null;
    }
    if (holdIntervalRef.current !== null) {
      window.clearInterval(holdIntervalRef.current);
      holdIntervalRef.current = null;
    }
  }, []);

  const stepDelta = React.useCallback(
    (dir: 1 | -1, multiplier = 1) => {
      const delta = step * multiplier * dir;
      return updateVal(currentVal + delta);
    },
    [currentVal, step, updateVal],
  );

  const startHold = React.useCallback(
    (dir: 1 | -1) => {
      if (disabled) return;
      stopHold();

      // Immediate first step
      const canMove = stepDelta(dir, 1);
      if (!canMove) return;

      holdStartRef.current = Date.now();

      // 300ms initial pause before rapid firing
      holdTimerRef.current = window.setTimeout(() => {
        const tick = () => {
          const elapsed = Date.now() - holdStartRef.current;
          let mult = 1;
          let intervalTime = 90;

          if (elapsed > 2400) {
            mult = Math.max(1, Math.round(effectiveLargeStep / step));
            intervalTime = 30;
          } else if (elapsed > 1200) {
            mult = Math.max(1, Math.round(effectiveLargeStep / step / 2));
            intervalTime = 55;
          }

          const ok = stepDelta(dir, mult);
          if (!ok) {
            stopHold();
            return;
          }

          holdIntervalRef.current = window.setTimeout(tick, intervalTime);
        };
        tick();
      }, 300);
    },
    [disabled, effectiveLargeStep, step, stepDelta, stopHold],
  );

  React.useEffect(() => {
    return () => stopHold();
  }, [stopHold]);

  const commitEdit = React.useCallback(() => {
    setEditing(false);
    const parsed = parseFloat(editText);
    if (!Number.isNaN(parsed)) {
      updateVal(parsed);
    } else {
      setEditText(String(currentVal));
    }
  }, [currentVal, editText, updateVal]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (disabled) return;

    if (e.key === "ArrowUp") {
      e.preventDefault();
      stepDelta(1, 1);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      stepDelta(-1, 1);
    } else if (e.key === "PageUp") {
      e.preventDefault();
      updateVal(currentVal + effectiveLargeStep);
    } else if (e.key === "PageDown") {
      e.preventDefault();
      updateVal(currentVal - effectiveLargeStep);
    } else if (e.key === "Home" && min !== -Infinity) {
      e.preventDefault();
      updateVal(min);
    } else if (e.key === "End" && max !== Infinity) {
      e.preventDefault();
      updateVal(max);
    } else if (editing) {
      if (e.key === "Enter") {
        e.preventDefault();
        commitEdit();
      } else if (e.key === "Escape") {
        e.preventDefault();
        setEditing(false);
        setEditText(String(currentVal));
      }
    }
  };

  const isSmall = size === "sm";
  const hCls = isSmall ? "h-7" : "h-9";
  const btnW = isSmall ? "w-7" : "w-8";
  const roundedCls = variant === "pill" ? "rounded-full" : "rounded-lg";

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label={label}
      tabIndex={disabled ? -1 : 0}
      onKeyDown={handleKeyDown}
      className={`inline-flex ${hCls} items-center border border-border bg-background p-0.5 select-none ${roundedCls} transition-[box-shadow,border-color] duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 ${disabled ? "opacity-50 pointer-events-none" : ""} ${className}`}
      style={{
        boxShadow: "0 0 0 1px transparent",
      }}
    >
      {/* Hidden input for HTML form submissions */}
      {name && <input type="hidden" name={name} value={currentVal} />}

      {/* Decrement Button */}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Decrease ${label}`}
        disabled={disabled || atMin}
        onPointerDown={(e) => {
          if (e.pointerType === "mouse" && e.button !== 0) return;
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {}
          startHold(-1);
        }}
        onPointerUp={(e) => {
          try {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) {
              e.currentTarget.releasePointerCapture(e.pointerId);
            }
          } catch {}
          stopHold();
        }}
        onPointerCancel={stopHold}
        className={`flex ${btnW} h-full items-center justify-center ${variant === "pill" ? "rounded-full" : "rounded-md"} text-muted-foreground transition-colors hover:bg-muted hover:text-foreground active:scale-95 disabled:pointer-events-none disabled:opacity-30 cursor-pointer disabled:cursor-default touch-manipulation`}
      >
        <MinusIcon />
      </button>

      {/* Value Display / Direct Edit */}
      <div
        className="relative flex min-w-[3.25rem] flex-1 items-center justify-center px-2 font-mono text-[13px] tabular-nums text-foreground cursor-text"
        onClick={() => {
          if (disabled || editing) return;
          setEditing(true);
          setEditText(String(currentVal));
          setTimeout(() => inputRef.current?.select(), 10);
        }}
      >
        {editing ? (
          <input
            ref={inputRef}
            type="text"
            inputMode="numeric"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onBlur={commitEdit}
            className="w-full bg-transparent text-center font-mono text-[13px] text-foreground outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
            autoFocus
          />
        ) : (
          <div className="flex items-baseline gap-1" aria-hidden="true">
            <NumberRoll value={currentVal} format={format} duration={260} />
            {unit && (
              <span className="font-sans text-[11px] text-muted-foreground">
                {unit}
              </span>
            )}
          </div>
        )}

        {/* Screen reader live value */}
        <span className="sr-only" role="status" aria-live="polite">
          {label}: {currentVal} {unit ?? ""}
        </span>
      </div>

      {/* Increment Button */}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Increase ${label}`}
        disabled={disabled || atMax}
        onPointerDown={(e) => {
          if (e.pointerType === "mouse" && e.button !== 0) return;
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {}
          startHold(1);
        }}
        onPointerUp={(e) => {
          try {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) {
              e.currentTarget.releasePointerCapture(e.pointerId);
            }
          } catch {}
          stopHold();
        }}
        onPointerCancel={stopHold}
        className={`flex ${btnW} h-full items-center justify-center ${variant === "pill" ? "rounded-full" : "rounded-md"} text-muted-foreground transition-colors hover:bg-muted hover:text-foreground active:scale-95 disabled:pointer-events-none disabled:opacity-30 cursor-pointer disabled:cursor-default touch-manipulation`}
      >
        <PlusIcon />
      </button>
    </div>
  );
}

